BEGIN;

INSERT INTO posts (
  author_id,
  title,
  summary,
  content,
  image_url,
  region_id,
  budget_range_id,
  theme_id,
  season,
  companion,
  travel_date,
  tags,
  view_count,
  created_at,
  updated_at
)
SELECT
  u.id,
  seed.title,
  seed.summary,
  seed.content,
  seed.image_url,
  r.id,
  b.id,
  t.id,
  seed.season::season_enum,
  seed.companion::companion_enum,
  seed.travel_date::date,
  seed.tags,
  seed.view_count,
  seed.created_at::timestamptz,
  seed.updated_at::timestamptz
FROM (
  VALUES
    ('traveler01', 'Busan relaxed coast and cafe day 1', 'Real-place plan built around Haeundae Beach, Geumsubokguk, and Signiel Busan.', 'A low-pressure route built around Haeundae Beach, Haedong Yonggungsa, a coffee stop at Geumsubokguk, and an easy check-in at Signiel Busan. I also liked how Huinnyeoul Culture Village fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=900&q=80', 'busan', 'from_100k_to_200k', 'healing', U&'\C5EC\B984', U&'\CE5C\AD6C', '2024-07-03', ARRAY['#busan', '#healing', '#haeundae_beach'], 180, '2026-06-12 09:00:00+09', '2026-06-12 09:00:00+09'),
    ('traveler01', 'Busan family stay with short transfers 2', 'Real-place plan built around Gwangalli Beach, Halmae Gaya Milmyeon, and Park Hyatt Busan.', 'This plan keeps walking manageable with Gwangalli Beach, a gentle stop at Songdo Marine Cable Car, dinner around Halmae Gaya Milmyeon, and a longer stay at Park Hyatt Busan. I also liked how Dongbaekseom fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=900&q=80', 'busan', 'over_300k', 'family', U&'\BD04', U&'\AC00\C871', '2025-04-06', ARRAY['#busan', '#family', '#gwangalli_beach'], 217, '2026-06-12 06:00:00+09', '2026-06-12 06:00:00+09'),
    ('traveler01', 'Busan sunset date course 3', 'Real-place plan built around Gamcheon Culture Village, Samjin Eomuk Busan Station, and Lotte Hotel Busan.', 'The route starts near Gamcheon Culture Village, shifts toward Huinnyeoul Culture Village for photos, ends with dinner at Samjin Eomuk Busan Station, and works well with an overnight at Lotte Hotel Busan. I also liked how Busan X the Sky fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=900&q=80', 'busan', 'from_200k_to_300k', 'date', U&'\AC00\C744', U&'\C5F0\C778', '2026-10-09', ARRAY['#busan', '#date', '#gamcheon_culture_village'], 254, '2026-06-12 03:00:00+09', '2026-06-12 03:00:00+09'),
    ('traveler01', 'Busan solo reset route 4', 'Real-place plan built around Haedong Yonggungsa, Haeundae Amsogalbi-jip, and Paradise Hotel Busan.', 'I used Haedong Yonggungsa as the main stop, kept the meal simple at Haeundae Amsogalbi-jip, and picked Paradise Hotel Busan only when I wanted one warm night instead of rushing home. I also liked how Jagalchi Market fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=900&q=80', 'busan', 'under_100k', 'solo_trip', U&'\ACA8\C6B8', U&'\D63C\C790', '2024-01-12', ARRAY['#busan', '#solo_trip', '#haedong_yonggungsa'], 291, '2026-06-12 00:00:00+09', '2026-06-12 00:00:00+09'),
    ('traveler01', 'Busan food-first one night plan 5', 'Real-place plan built around Songdo Marine Cable Car, Geumsubokguk, and Signiel Busan.', 'The key stops were Geumsubokguk, Halmae Gaya Milmyeon, and a market or walk around Songdo Marine Cable Car. I stayed at Signiel Busan so the morning move to Busan X the Sky stayed easy. I also liked how Blueline Park fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=900&q=80', 'busan', 'from_100k_to_200k', 'gourmet', U&'\C5EC\B984', U&'\CE5C\AD6C', '2025-07-15', ARRAY['#busan', '#gourmet', '#songdo_marine_cable_car'], 328, '2026-06-11 21:00:00+09', '2026-06-11 21:00:00+09'),
    ('traveler01', 'Busan scenic drive loop 6', 'Real-place plan built around Huinnyeoul Culture Village, Halmae Gaya Milmyeon, and Park Hyatt Busan.', 'The whole point was the drive between Huinnyeoul Culture Village and Jagalchi Market. We used Park Hyatt Busan as a stable base and kept lunch around Halmae Gaya Milmyeon instead of adding extra detours. I also liked how Haeundae Beach fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=900&q=80', 'busan', 'from_200k_to_300k', 'drive', U&'\BD04', U&'\AC00\C871', '2026-04-18', ARRAY['#busan', '#drive', '#huinnyeoul_culture_village'], 365, '2026-06-11 18:00:00+09', '2026-06-11 18:00:00+09'),
    ('traveler01', 'Busan premium anniversary stay 7', 'Real-place plan built around Dongbaekseom, Samjin Eomuk Busan Station, and Lotte Hotel Busan.', 'For a special trip, the combination of Lotte Hotel Busan, Dongbaekseom, Blueline Park, and a reservation at Samjin Eomuk Busan Station felt balanced without becoming too packed. I also liked how Gwangalli Beach fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=900&q=80', 'busan', 'over_300k', 'couple', U&'\AC00\C744', U&'\C5F0\C778', '2024-10-21', ARRAY['#busan', '#couple', '#dongbaekseom'], 402, '2026-06-11 15:00:00+09', '2026-06-11 15:00:00+09'),
    ('traveler01', 'Busan budget local food route 8', 'Real-place plan built around Busan X the Sky, Haeundae Amsogalbi-jip, and Paradise Hotel Busan.', 'This version cuts taxi use and focuses on Haeundae Amsogalbi-jip, Geumsubokguk, and one main view at Busan X the Sky. For the budget, it still felt satisfying. I also liked how Gamcheon Culture Village fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=900&q=80', 'busan', 'under_100k', 'gourmet', U&'\ACA8\C6B8', U&'\CE5C\AD6C', '2025-01-24', ARRAY['#busan', '#gourmet', '#busan_x_the_sky'], 439, '2026-06-11 12:00:00+09', '2026-06-11 12:00:00+09'),
    ('traveler01', 'Busan museum and easy meal backup 9', 'Real-place plan built around Jagalchi Market, Geumsubokguk, and Signiel Busan.', 'When weather felt uncertain, Jagalchi Market and Gwangalli Beach were dependable picks. We stayed close to Signiel Busan and used Geumsubokguk as the safest meal stop. I also liked how Haedong Yonggungsa fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=900&q=80', 'busan', 'from_100k_to_200k', 'family', U&'\BD04', U&'\AC00\C871', '2026-04-03', ARRAY['#busan', '#family', '#jagalchi_market'], 476, '2026-06-11 09:00:00+09', '2026-06-11 09:00:00+09'),
    ('traveler01', 'Busan quiet photo and stay route 10', 'Real-place plan built around Blueline Park, Halmae Gaya Milmyeon, and Park Hyatt Busan.', 'I wanted a slower pace, so I paired Blueline Park with a longer break near Gamcheon Culture Village, then wrapped the day with Halmae Gaya Milmyeon and a simple room at Park Hyatt Busan. I also liked how Songdo Marine Cable Car fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=900&q=80', 'busan', 'from_200k_to_300k', 'healing', U&'\AC00\C744', U&'\D63C\C790', '2024-10-06', ARRAY['#busan', '#healing', '#blueline_park'], 513, '2026-06-11 06:00:00+09', '2026-06-11 06:00:00+09'),
    ('traveler02', 'Jeju relaxed coast and cafe day 1', 'Real-place plan built around Seongsan Ilchulbong, Myeongjin Jeonbok, and Lotte Hotel Jeju.', 'A low-pressure route built around Seongsan Ilchulbong, Osulloc Tea Museum, a coffee stop at Myeongjin Jeonbok, and an easy check-in at Lotte Hotel Jeju. I also liked how Woljeongri Beach fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=900&q=80', 'jeju', 'from_100k_to_200k', 'healing', U&'\C5EC\B984', U&'\CE5C\AD6C', '2025-07-05', ARRAY['#jeju', '#healing', '#seongsan_ilchulbong'], 270, '2026-06-11 23:00:00+09', '2026-06-11 23:00:00+09'),
    ('traveler02', 'Jeju family stay with short transfers 2', 'Real-place plan built around Udo, Ujin Haejangguk, and The Shilla Jeju.', 'This plan keeps walking manageable with Udo, a gentle stop at Hyeopjae Beach, dinner around Ujin Haejangguk, and a longer stay at The Shilla Jeju. I also liked how Manjanggul Cave fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=900&q=80', 'jeju', 'over_300k', 'family', U&'\BD04', U&'\AC00\C871', '2026-04-08', ARRAY['#jeju', '#family', '#udo'], 307, '2026-06-11 20:00:00+09', '2026-06-11 20:00:00+09'),
    ('traveler02', 'Jeju sunset date course 3', 'Real-place plan built around Seopjikoji, Jamae Guksu, and Grand Hyatt Jeju.', 'The route starts near Seopjikoji, shifts toward Woljeongri Beach for photos, ends with dinner at Jamae Guksu, and works well with an overnight at Grand Hyatt Jeju. I also liked how Camellia Hill fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=900&q=80', 'jeju', 'from_200k_to_300k', 'date', U&'\AC00\C744', U&'\C5F0\C778', '2024-10-11', ARRAY['#jeju', '#date', '#seopjikoji'], 344, '2026-06-11 17:00:00+09', '2026-06-11 17:00:00+09'),
    ('traveler02', 'Jeju solo reset route 4', 'Real-place plan built around Osulloc Tea Museum, Donsadon, and Maison Glad Jeju.', 'I used Osulloc Tea Museum as the main stop, kept the meal simple at Donsadon, and picked Maison Glad Jeju only when I wanted one warm night instead of rushing home. I also liked how Hallim Park fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=900&q=80', 'jeju', 'under_100k', 'solo_trip', U&'\ACA8\C6B8', U&'\D63C\C790', '2025-01-14', ARRAY['#jeju', '#solo_trip', '#osulloc_tea_museum'], 381, '2026-06-11 14:00:00+09', '2026-06-11 14:00:00+09'),
    ('traveler02', 'Jeju food-first one night plan 5', 'Real-place plan built around Hyeopjae Beach, Myeongjin Jeonbok, and Lotte Hotel Jeju.', 'The key stops were Myeongjin Jeonbok, Ujin Haejangguk, and a market or walk around Hyeopjae Beach. I stayed at Lotte Hotel Jeju so the morning move to Camellia Hill stayed easy. I also liked how Jeju Stone Park fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=900&q=80', 'jeju', 'from_100k_to_200k', 'gourmet', U&'\C5EC\B984', U&'\CE5C\AD6C', '2026-07-17', ARRAY['#jeju', '#gourmet', '#hyeopjae_beach'], 418, '2026-06-11 11:00:00+09', '2026-06-11 11:00:00+09'),
    ('traveler02', 'Jeju scenic drive loop 6', 'Real-place plan built around Woljeongri Beach, Ujin Haejangguk, and The Shilla Jeju.', 'The whole point was the drive between Woljeongri Beach and Hallim Park. We used The Shilla Jeju as a stable base and kept lunch around Ujin Haejangguk instead of adding extra detours. I also liked how Seongsan Ilchulbong fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=900&q=80', 'jeju', 'from_200k_to_300k', 'drive', U&'\BD04', U&'\AC00\C871', '2024-04-20', ARRAY['#jeju', '#drive', '#woljeongri_beach'], 455, '2026-06-11 08:00:00+09', '2026-06-11 08:00:00+09'),
    ('traveler02', 'Jeju premium anniversary stay 7', 'Real-place plan built around Manjanggul Cave, Jamae Guksu, and Grand Hyatt Jeju.', 'For a special trip, the combination of Grand Hyatt Jeju, Manjanggul Cave, Jeju Stone Park, and a reservation at Jamae Guksu felt balanced without becoming too packed. I also liked how Udo fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=900&q=80', 'jeju', 'over_300k', 'couple', U&'\AC00\C744', U&'\C5F0\C778', '2025-10-23', ARRAY['#jeju', '#couple', '#manjanggul_cave'], 492, '2026-06-11 05:00:00+09', '2026-06-11 05:00:00+09'),
    ('traveler02', 'Jeju budget local food route 8', 'Real-place plan built around Camellia Hill, Donsadon, and Maison Glad Jeju.', 'This version cuts taxi use and focuses on Donsadon, Myeongjin Jeonbok, and one main view at Camellia Hill. For the budget, it still felt satisfying. I also liked how Seopjikoji fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=900&q=80', 'jeju', 'under_100k', 'gourmet', U&'\ACA8\C6B8', U&'\CE5C\AD6C', '2026-01-26', ARRAY['#jeju', '#gourmet', '#camellia_hill'], 529, '2026-06-11 02:00:00+09', '2026-06-11 02:00:00+09'),
    ('traveler02', 'Jeju museum and easy meal backup 9', 'Real-place plan built around Hallim Park, Myeongjin Jeonbok, and Lotte Hotel Jeju.', 'When weather felt uncertain, Hallim Park and Udo were dependable picks. We stayed close to Lotte Hotel Jeju and used Myeongjin Jeonbok as the safest meal stop. I also liked how Osulloc Tea Museum fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=900&q=80', 'jeju', 'from_100k_to_200k', 'family', U&'\BD04', U&'\AC00\C871', '2024-04-05', ARRAY['#jeju', '#family', '#hallim_park'], 566, '2026-06-10 23:00:00+09', '2026-06-10 23:00:00+09'),
    ('traveler02', 'Jeju quiet photo and stay route 10', 'Real-place plan built around Jeju Stone Park, Ujin Haejangguk, and The Shilla Jeju.', 'I wanted a slower pace, so I paired Jeju Stone Park with a longer break near Seopjikoji, then wrapped the day with Ujin Haejangguk and a simple room at The Shilla Jeju. I also liked how Hyeopjae Beach fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=900&q=80', 'jeju', 'from_200k_to_300k', 'healing', U&'\AC00\C744', U&'\D63C\C790', '2025-10-08', ARRAY['#jeju', '#healing', '#jeju_stone_park'], 603, '2026-06-10 20:00:00+09', '2026-06-10 20:00:00+09'),
    ('traveler03', 'Gangneung relaxed coast and cafe day 1', 'Real-place plan built around Gyeongpo Beach, Terarosa Coffee Gongjang, and SEAMARQ Hotel.', 'A low-pressure route built around Gyeongpo Beach, Haslla Art World, a coffee stop at Terarosa Coffee Gongjang, and an easy check-in at SEAMARQ Hotel. I also liked how Seongyojang fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1500534314209-a25ddb2bd429?auto=format&fit=crop&w=900&q=80', 'gangneung', 'from_100k_to_200k', 'healing', U&'\C5EC\B984', U&'\CE5C\AD6C', '2026-07-07', ARRAY['#gangneung', '#healing', '#gyeongpo_beach'], 360, '2026-06-11 13:00:00+09', '2026-06-11 13:00:00+09'),
    ('traveler03', 'Gangneung family stay with short transfers 2', 'Real-place plan built around Anmok Coffee Street, Donghwa Garden, and Skybay Hotel Gyeongpo.', 'This plan keeps walking manageable with Anmok Coffee Street, a gentle stop at Jumunjin Breakwater, dinner around Donghwa Garden, and a longer stay at Skybay Hotel Gyeongpo. I also liked how Gangneung Jungang Market fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1500534314209-a25ddb2bd429?auto=format&fit=crop&w=900&q=80', 'gangneung', 'over_300k', 'family', U&'\BD04', U&'\AC00\C871', '2024-04-10', ARRAY['#gangneung', '#family', '#anmok_coffee_street'], 397, '2026-06-11 10:00:00+09', '2026-06-11 10:00:00+09'),
    ('traveler03', 'Gangneung sunset date course 3', 'Real-place plan built around Ojukheon, Daedong Myeonok, and St. John''s Hotel.', 'The route starts near Ojukheon, shifts toward Seongyojang for photos, ends with dinner at Daedong Myeonok, and works well with an overnight at St. John''s Hotel. I also liked how Heo Gyun and Heo Nanseolheon Memorial Park fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1500534314209-a25ddb2bd429?auto=format&fit=crop&w=900&q=80', 'gangneung', 'from_200k_to_300k', 'date', U&'\AC00\C744', U&'\C5F0\C778', '2025-10-13', ARRAY['#gangneung', '#date', '#ojukheon'], 434, '2026-06-11 07:00:00+09', '2026-06-11 07:00:00+09'),
    ('traveler03', 'Gangneung solo reset route 4', 'Real-place plan built around Haslla Art World, Chodang Sundubu Village, and SEAMARQ Hotel.', 'I used Haslla Art World as the main stop, kept the meal simple at Chodang Sundubu Village, and picked SEAMARQ Hotel only when I wanted one warm night instead of rushing home. I also liked how Sacheon Beach fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1500534314209-a25ddb2bd429?auto=format&fit=crop&w=900&q=80', 'gangneung', 'under_100k', 'solo_trip', U&'\ACA8\C6B8', U&'\D63C\C790', '2026-01-16', ARRAY['#gangneung', '#solo_trip', '#haslla_art_world'], 471, '2026-06-11 04:00:00+09', '2026-06-11 04:00:00+09'),
    ('traveler03', 'Gangneung food-first one night plan 5', 'Real-place plan built around Jumunjin Breakwater, Terarosa Coffee Gongjang, and Skybay Hotel Gyeongpo.', 'The key stops were Terarosa Coffee Gongjang, Donghwa Garden, and a market or walk around Jumunjin Breakwater. I stayed at Skybay Hotel Gyeongpo so the morning move to Heo Gyun and Heo Nanseolheon Memorial Park stayed easy. I also liked how Chodang Sundubu Village fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1500534314209-a25ddb2bd429?auto=format&fit=crop&w=900&q=80', 'gangneung', 'from_100k_to_200k', 'gourmet', U&'\C5EC\B984', U&'\CE5C\AD6C', '2024-07-19', ARRAY['#gangneung', '#gourmet', '#jumunjin_breakwater'], 508, '2026-06-11 01:00:00+09', '2026-06-11 01:00:00+09'),
    ('traveler03', 'Gangneung scenic drive loop 6', 'Real-place plan built around Seongyojang, Donghwa Garden, and St. John''s Hotel.', 'The whole point was the drive between Seongyojang and Sacheon Beach. We used St. John''s Hotel as a stable base and kept lunch around Donghwa Garden instead of adding extra detours. I also liked how Gyeongpo Beach fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1500534314209-a25ddb2bd429?auto=format&fit=crop&w=900&q=80', 'gangneung', 'from_200k_to_300k', 'drive', U&'\BD04', U&'\AC00\C871', '2025-04-22', ARRAY['#gangneung', '#drive', '#seongyojang'], 545, '2026-06-10 22:00:00+09', '2026-06-10 22:00:00+09'),
    ('traveler03', 'Gangneung premium anniversary stay 7', 'Real-place plan built around Gangneung Jungang Market, Daedong Myeonok, and SEAMARQ Hotel.', 'For a special trip, the combination of SEAMARQ Hotel, Gangneung Jungang Market, Chodang Sundubu Village, and a reservation at Daedong Myeonok felt balanced without becoming too packed. I also liked how Anmok Coffee Street fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1500534314209-a25ddb2bd429?auto=format&fit=crop&w=900&q=80', 'gangneung', 'over_300k', 'couple', U&'\AC00\C744', U&'\C5F0\C778', '2026-10-25', ARRAY['#gangneung', '#couple', '#gangneung_jungang_market'], 582, '2026-06-10 19:00:00+09', '2026-06-10 19:00:00+09'),
    ('traveler03', 'Gangneung budget local food route 8', 'Real-place plan built around Heo Gyun and Heo Nanseolheon Memorial Park, Chodang Sundubu Village, and Skybay Hotel Gyeongpo.', 'This version cuts taxi use and focuses on Chodang Sundubu Village, Terarosa Coffee Gongjang, and one main view at Heo Gyun and Heo Nanseolheon Memorial Park. For the budget, it still felt satisfying. I also liked how Ojukheon fit into the route without forcing a rushed checkout.', 'https://images.unsplash.com/photo-1500534314209-a25ddb2bd429?auto=format&fit=crop&w=900&q=80', 'gangneung', 'under_100k', 'gourmet', U&'\ACA8\C6B8', U&'\CE5C\AD6C', '2024-01-04', ARRAY['#gangneung', '#gourmet', '#heo_gyun_and_heo_nanseolheon_memorial_park'], 619, '2026-06-10 16:00:00+09', '2026-06-10 16:00:00+09'),
